-- Más ejercicios para que las rutinas varíen de verdad (antes cada familia tenía 2 o 3 opciones y se alternaban A/B).
-- Todos se pueden hacer en un gym tipo Smart Fit (máquinas, poleas, mancuernas, Multipower, colchonetas, cajones).
-- Se agregan a cada hogar solo los que no tiene (por nombre). Sin imagen: la ficha muestra la técnica.
with nuevos(nombre, grupo, unidad, por_lado, tecnica) as (values
  ('Flexiones de brazos', 'Pecho', 'reps', false, array['Manos un poco más abiertas que los hombros, cuerpo recto de cabeza a talones.', 'Baja hasta casi tocar el piso con el pecho y empuja. Si cuesta, apoya las rodillas.']),
  ('Flexiones con pies elevados', 'Pecho superior', 'reps', false, array['Pies sobre un banco o cajón, manos en el piso.', 'Baja controlado y empuja sin arquear la espalda.']),
  ('Press de pecho en polea de pie', 'Pecho', 'reps', false, array['Poleas a la altura del pecho, un pie adelante.', 'Empuja hacia adelante juntando las manos y vuelve lento.']),
  ('Press inclinado en polea', 'Pecho superior', 'reps', false, array['Poleas abajo, banco inclinado entre ellas.', 'Empuja hacia arriba y adentro, sin trabar los codos.']),
  ('Aperturas con mancuernas en banco', 'Pecho', 'reps', false, array['Acostado, codos apenas flexionados.', 'Abre los brazos hasta sentir el estiramiento del pecho y cierra arriba.']),
  ('Cruce de poleas desde abajo', 'Pecho superior', 'reps', false, array['Poleas abajo, sube las manos en arco hasta la altura de los ojos.', 'Aprieta el pecho arriba y baja lento.']),
  ('Press Arnold con mancuernas', 'Hombros', 'reps', false, array['Sentado, mancuernas frente a la cara con palmas hacia ti.', 'Sube girando las palmas hacia adelante; baja deshaciendo el giro.']),
  ('Press militar en Multipower', 'Hombros', 'reps', false, array['Sentado en banco vertical, barra a la altura del mentón.', 'Empuja hasta arriba sin arquear la zona lumbar.']),
  ('Elevación lateral en polea a una mano', 'Hombros', 'reps', true, array['Polea abajo, cable cruzando por delante del cuerpo.', 'Sube el brazo de lado hasta la altura del hombro, lento.']),
  ('Elevación lateral sentado con mancuernas', 'Hombros', 'reps', false, array['Sentado al borde del banco, espalda recta.', 'Sube los brazos de lado hasta los hombros, sin balancear.']),
  ('Pec deck inverso', 'Hombro posterior', 'reps', false, array['Sentado mirando a la máquina, agarres a la altura de los hombros.', 'Abre los brazos hacia atrás juntando los omóplatos.']),
  ('Pájaros en polea cruzada', 'Hombro posterior', 'reps', false, array['Poleas altas cruzadas, un cable en cada mano.', 'Abre los brazos hacia atrás a la altura de los hombros.']),
  ('Extensión de tríceps sobre la cabeza en polea', 'Tríceps', 'reps', false, array['De espaldas a la polea, cuerda detrás de la cabeza.', 'Extiende los codos hacia adelante y arriba sin abrirlos.']),
  ('Press francés con mancuernas', 'Tríceps', 'reps', false, array['Acostado, mancuernas arriba con palmas enfrentadas.', 'Dobla solo los codos bajando junto a la cabeza y extiende.']),
  ('Patada de tríceps en polea', 'Tríceps', 'reps', true, array['Inclinado, codo pegado al costado.', 'Extiende el brazo hacia atrás y aprieta el tríceps.']),
  ('Fondos en banco', 'Tríceps', 'reps', false, array['Manos en el banco detrás de ti, piernas estiradas o dobladas.', 'Baja doblando los codos hacia atrás y empuja.']),
  ('Jalón con agarre neutro', 'Espalda', 'reps', false, array['Agarre en V con palmas enfrentadas.', 'Tira hacia el pecho bajando los hombros y llevando los codos al costado.']),
  ('Jalón unilateral en polea', 'Espalda', 'reps', true, array['Arrodillado o sentado, una mano en la polea alta.', 'Tira el codo hacia la cadera y estira bien arriba.']),
  ('Remo en polea baja a una mano', 'Espalda', 'reps', true, array['Sentado o de pie, una mano en la polea baja.', 'Tira hacia la cadera sin girar el tronco.']),
  ('Remo con pecho apoyado con mancuernas', 'Espalda', 'reps', false, array['Boca abajo en un banco inclinado.', 'Rema llevando los codos atrás y junta los omóplatos.']),
  ('Pullover con mancuerna', 'Espalda', 'reps', false, array['Acostado en el banco, una mancuerna con las dos manos.', 'Baja detrás de la cabeza con codos apenas flexionados y vuelve.']),
  ('Remo abierto en polea baja', 'Espalda alta', 'reps', false, array['Barra larga, agarre ancho.', 'Tira hacia el pecho con los codos abiertos.']),
  ('Remo alto con mancuernas en banco inclinado', 'Espalda alta', 'reps', false, array['Boca abajo en banco inclinado.', 'Rema con los codos abiertos a la altura de los hombros.']),
  ('Curl en polea baja con barra', 'Bíceps', 'reps', false, array['De pie frente a la polea baja.', 'Sube doblando los codos sin moverlos de los costados.']),
  ('Curl inclinado con mancuernas', 'Bíceps', 'reps', false, array['Banco inclinado, brazos colgando atrás.', 'Sube sin adelantar los codos; buen estiramiento abajo.']),
  ('Curl concentrado', 'Bíceps', 'reps', true, array['Sentado, codo apoyado en la parte interna del muslo.', 'Sube lento y aprieta arriba.']),
  ('Curl en banco Scott con mancuerna', 'Bíceps', 'reps', true, array['Brazo apoyado en el banco predicador.', 'Baja casi hasta estirar y sube sin despegar el brazo.']),
  ('Curl martillo en polea con cuerda', 'Bíceps y antebrazos', 'reps', false, array['Polea baja con cuerda, palmas enfrentadas.', 'Sube sin mover los codos.']),
  ('Curl martillo cruzado', 'Bíceps y antebrazos', 'reps', true, array['Mancuerna con agarre neutro.', 'Sube cruzando hacia el hombro contrario.']),
  ('Colgarse de la barra', 'Agarre', 'segundos', false, array['Cuélgate de la barra de dominadas con brazos estirados.', 'Hombros activos (no colgados de las orejas).']),
  ('Encogimientos en polea', 'Trapecios', 'reps', false, array['De pie entre las poleas bajas o con barra en polea.', 'Sube los hombros hacia las orejas y baja lento.']),
  ('Sentadilla goblet con mancuerna', 'Piernas', 'reps', false, array['Mancuerna pegada al pecho.', 'Baja con el pecho alto y las rodillas siguiendo la punta de los pies.']),
  ('Hip thrust a una pierna', 'Glúteos', 'reps', true, array['Espalda alta en el banco, un pie en el piso.', 'Empuja la cadera arriba con esa pierna y aprieta el glúteo.']),
  ('Puente de glúteo con mancuerna', 'Glúteos', 'reps', false, array['Acostado en el piso, mancuerna en la cadera.', 'Sube la cadera apretando glúteos, sin arquear la espalda.']),
  ('Patada de glúteo en polea', 'Glúteos', 'reps', true, array['Tobillera en la polea baja.', 'Lleva la pierna atrás apretando el glúteo, sin arquear la espalda.']),
  ('Abducción de cadera en polea', 'Glúteos', 'reps', true, array['Tobillera en la polea baja, de lado a la máquina.', 'Abre la pierna hacia afuera, controlado.']),
  ('Caminata lateral con banda', 'Glúteos', 'reps', false, array['Banda sobre las rodillas o tobillos, semi sentadilla.', 'Pasos laterales sin juntar los pies.']),
  ('Peso muerto rumano en Multipower', 'Isquiotibiales', 'reps', false, array['Barra pegada a los muslos, rodillas apenas flexionadas.', 'Lleva la cadera atrás bajando la barra por las piernas y vuelve.']),
  ('Peso muerto rumano a una pierna', 'Isquiotibiales', 'reps', true, array['Una mancuerna, apoyado en una pierna.', 'Inclínate llevando la otra pierna atrás, espalda recta.']),
  ('Buenos días en Multipower', 'Isquiotibiales', 'reps', false, array['Barra sobre los hombros, rodillas apenas flexionadas.', 'Inclina el tronco llevando la cadera atrás y vuelve. Liviano.']),
  ('Curl femoral sentado en máquina', 'Isquiotibiales', 'reps', false, array['Rodillo sobre los tobillos, rodillas alineadas con el eje.', 'Dobla las rodillas llevando los talones abajo y vuelve lento.']),
  ('Curl femoral con fitball', 'Isquiotibiales', 'reps', false, array['Acostado, talones sobre la pelota y cadera arriba.', 'Trae la pelota hacia ti doblando las rodillas.']),
  ('Curl nórdico asistido', 'Isquiotibiales', 'reps', false, array['De rodillas con los tobillos sujetos.', 'Baja el cuerpo lento hacia adelante; ayúdate con las manos al final.']),
  ('Plancha Copenhague', 'Aductores', 'segundos', true, array['Plancha lateral con la pierna de arriba apoyada en un banco.', 'Mantén la cadera alta. Empieza con la rodilla apoyada.']),
  ('Sentadilla sumo con mancuerna', 'Aductores', 'reps', false, array['Pies bien abiertos, puntas afuera, mancuerna colgando.', 'Baja recto y sube apretando la parte interna del muslo.']),
  ('Elevación de talones en Multipower', 'Pantorrillas', 'reps', false, array['De pie bajo la barra, puntas en un disco o escalón.', 'Sube en puntas y baja hasta estirar.']),
  ('Elevación de talones a una pierna', 'Pantorrillas', 'reps', true, array['En un escalón, apoyado en una pierna.', 'Sube en punta y baja lento.']),
  ('Dead bug', 'Core', 'reps', false, array['Boca arriba, brazos y rodillas arriba.', 'Estira brazo y pierna contrarios sin despegar la zona lumbar.']),
  ('Plancha con toque de hombros', 'Core', 'reps', false, array['Plancha alta con pies separados.', 'Toca el hombro contrario sin mover la cadera.']),
  ('Elevación de piernas colgado', 'Core', 'reps', false, array['Colgado de la barra.', 'Sube las rodillas (o piernas estiradas) sin balancearte.']),
  ('Crunch en polea de rodillas', 'Core', 'reps', false, array['De rodillas frente a la polea alta con cuerda.', 'Enrolla el tronco hacia abajo con el abdomen.']),
  ('Elevación de piernas en colchoneta', 'Core', 'reps', false, array['Boca arriba, manos bajo la cadera.', 'Sube y baja las piernas sin despegar la zona lumbar.']),
  ('Woodchop en polea', 'Core', 'reps', true, array['Polea alta, tira en diagonal hacia la rodilla contraria.', 'Gira desde el tronco con los brazos firmes.']),
  ('Giro ruso con disco', 'Core', 'reps', false, array['Sentado, pies apoyados o en el aire, disco en el pecho.', 'Gira el tronco de lado a lado.']),
  ('Hiperextensión en banco romano', 'Zona lumbar', 'reps', false, array['Cadera apoyada en el banco, pies sujetos.', 'Baja el tronco y sube hasta alinear, sin pasarte atrás.']),
  ('Alcance en estrella a una pierna', 'Estabilidad', 'reps', true, array['Apoyado en una pierna.', 'Toca con el otro pie adelante, al costado y atrás, sin perder el equilibrio.']),
  ('Saltos laterales al cajón', 'Pliometría', 'reps', true, array['De lado al cajón bajo.', 'Salta de lado arriba y baja; aterriza suave.']),
  ('Saltos laterales sobre línea', 'Pliometría', 'segundos', false, array['Pies juntos al lado de una línea.', 'Salta rápido de lado a lado, tocando poco el piso.']),
  ('Sentadilla con salto', 'Pliometría', 'reps', false, array['Sentadilla y salta hacia arriba.', 'Aterriza suave doblando las rodillas.']),
  ('Salto al cajón', 'Pliometría', 'reps', false, array['Frente a un cajón de altura cómoda.', 'Salta arriba con los dos pies y baja caminando.'])
)
insert into public.ejercicios (hogar_id, nombre, grupo_muscular, unidad, por_lado, tecnica, imagenes)
select h.id, n.nombre, n.grupo, n.unidad, n.por_lado, n.tecnica, '{}'
from public.hogares h cross join nuevos n
where not exists (select 1 from public.ejercicios e where e.hogar_id = h.id and lower(e.nombre) = lower(n.nombre));
